mapper.update:
update setmeal
category_id=#{categoryId}, name=#{name}, update_user=#{updateUser}, update_time=#{updateTime}, status=#{status}, price=#{price}, description=#{description}, image=#{image},
where id=#{id}

mapper.select:
select * from setmeal


        and category_id = #{categoryId}


        and status = #{status}

select s.*,c.name categoryname from setmeal s left outer join category c on s.category_id=c.id

     and s.name like concat('%',#{name},'%')
    and s.status=#{status}
    and s.category_id=#{categoryId}

order by s.create_time desc
